// Tiny loader for the problem bank. index.json is generated by tools/build-index.js.
export async function loadIndex(base = "../problems/") {
  const r = await fetch(base + "index.json");
  if (!r.ok) throw new Error("could not load problem index");
  return r.json();
}

export async function loadProblem(id, base = "../problems/") {
  const r = await fetch(`${base}${id}.json`);
  if (!r.ok) throw new Error("could not load problem " + id);
  return r.json();
}
